  : 'This platform has no safe posting API. After approval you get the final text to paste into the thread yourself.';

const body = `
<h1>Review backlink candidate</h1>
<p class="meta">Platform: <b>${esc(row.platform)}</b> &middot; Solution: <b>${esc(row.solution_title)}</b> &middot; Match score: <b>${esc(row.match_score)}</b></p>
<div class="card">
  <p><a href="${esc(safeUrl(row.post_url))}" target="_blank" rel="noopener">${esc(row.post_title || row.post_url)}</a></p>
  <p class="meta"><b>Matched problem:</b> ${esc(row.matched_problem)}</p>
  <p class="meta"><b>Why relevant:</b> ${esc(row.relevance_reason)}</p>
</div>
<form method="POST" action="/webhook/backlink-review-submit">
  <input type="hidden" name="id" value="${esc(row.id)}">
  <input type="hidden" name="token" value="${esc(row.review_token)}">
  <label for="answer"><b>Answer (edit before approving)</b></label>
  <textarea id="answer" name="answer" rows="12"${maxAttr}>${esc(row.answer)}</textarea>
  <p class="warn">${esc(limitNote)}<br>If the text contains a SyaCo link it must also say you work at SyaCo (disclosure).${row.link_included ? '' : ' The AI did not include a link in this draft.'}</p>
  <p>
    <button class="ok" type="submit" name="action" value="approve">Approve</button>
    <button class="no" type="submit" name="action" value="reject" formnovalidate>Reject</button>
  </p>
</form>`;
return [{ json: { html: page('Review backlink candidate', body) } }];

