const row = $input.first().json;
const fail = (msg) => [{ json: { ok: false, id: row.id, error: msg, answer: row.answer, post_url: row.post_url } }];

const m = String(row.post_url || '').match(/^https:\/\/bsky\.app\/profile\/([^/]+)\/post\/([A-Za-z0-9]+)$/);
if (!m) return fail('Could not parse the Bluesky post URL');

const text = String(row.answer || '').trim();
const graphemes = (typeof Intl !== 'undefined' && Intl.Segmenter)
  ? Array.from(new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text)).length
  : Array.from(text).length;
if (graphemes > 300) return fail(`Text is ${graphemes} characters; Bluesky allows 300`);

// UTF-8 length computed by hand: Buffer / TextEncoder are not guaranteed in every n8n Code node sandbox.
const byteLen = (s) => {
  let n = 0;
  for (const ch of String(s)) {
    const c = ch.codePointAt(0);
    n += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4;
  }
  return n;
};
const facets = [];
const re = /https?:\/\/[^\s]+/g;
let mm;
while ((mm = re.exec(text)) !== null) {
  const url = mm[0].replace(/[.,;:!?)\]]+$/, '');
  const byteStart = byteLen(text.slice(0, mm.index));
  facets.push({
    index: { byteStart, byteEnd: byteStart + byteLen(url) },
    features: [{ $type: 'app.bsky.richtext.facet#link', uri: url }]
  });
}
return [{ json: { ok: true, id: row.id, actor: m[1], rkey: m[2], text, facets, answer: row.answer, post_url: row.post_url } }];

const prep = $('Prepare Bluesky Post').first().json;
const session = $('Create Bluesky Session').first().json;
const profile = $('Resolve Actor DID').first().json;
const posts = $input.first().json;
const short = (v) => JSON.stringify(v).slice(0, 300);
const fail = (msg) => [{ json: { ok: false, id: prep.id, error: msg, answer: prep.answer, post_url: prep.post_url } }];

if (!session.accessJwt || !session.did) return fail('Bluesky login failed: ' + short(session));
if (!profile.did) return fail('Could not resolve the author of the Bluesky post: ' + short(profile));
const parent = posts.posts && posts.posts[0];
if (!parent || !parent.uri || !parent.cid) return fail('Could not load the Bluesky post to reply to (deleted or private?)');

const root = parent.record?.reply?.root?.uri ? parent.record.reply.root : { uri: parent.uri, cid: parent.cid };
const record = {
  $type: 'app.bsky.feed.post',
  text: prep.text,
  createdAt: new Date().toISOString(),
  reply: {
    root: { uri: root.uri, cid: root.cid },
    parent: { uri: parent.uri, cid: parent.cid }
  }
};
if (prep.facets && prep.facets.length) record.facets = prep.facets;

return [{ json: {
  ok: true,
  id: prep.id,
  handle: session.handle,
  accessJwt: session.accessJwt,
  answer: prep.answer,
  post_url: prep.post_url,
  createRecordBody: { repo: session.did, collection: 'app.bsky.feed.post', record }
} }];

const prev = $('Build Reply Record').first().json;
const res = $input.first().json;
if (!res.uri) {
  return [{ json: { ok: false, id: prev.id, error: 'Bluesky rejected the post: ' + JSON.stringify(res).slice(0, 300), answer: prev.answer, post_url: prev.post_url } }];
}
const rkey = String(res.uri).split('/').pop();
return [{ json: { ok: true, id: prev.id, postedUrl: `https://bsky.app/profile/${prev.handle}/post/${rkey}`, answer: prev.answer, post_url: prev.post_url } }];

